describe("doctests of sympy.series.order", () => {
  it("O(x + x**2)", () => {
    const x = new Sym('x');
    expect(sympyStr(O(add(x, pow(x, 2))))).toBe('O(x)');
  });
  it("O(x + x**2, (x, 0))", () => {
    const x = new Sym('x');
    expect(sympyStr(O(add(x, pow(x, 2)), x, rational(0)))).toBe('O(x)');
  });
  it("O(x + x**2, (x, oo))", () => {
    const x = new Sym('x');
    expect(sympyStr(O(add(x, pow(x, 2)), x, oo))).toBe('O(x**2, (x, oo))');
  });
  it("O(1 + x*y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(O(add(1, mul(x, y))))).toBe('O(1, x, y)');
  });
  it("O(1 + x*y, (x, 0), (y, 0))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(O(add(1, mul(x, y)), [x, y], rational(0)))).toBe('O(1, x, y)');
  });
  it("O(1 + x*y, (x, oo), (y, oo))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(O(add(1, mul(x, y)), [x, y], oo))).toBe('O(x*y, (x, oo), (y, oo))');
  });
  // the arguments do not type-check against the public API
  //   O(1) in O(1, x)
  //   => True
  it.todo("O(1) in O(1, x)");
  it("O(1, x) in O(1)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  // the arguments do not type-check against the public API
  //   O(x) in O(1, x)
  //   => True
  it.todo("O(x) in O(1, x)");
  // the arguments do not type-check against the public API
  //   O(x**2) in O(x)
  //   => True
  it.todo("O(x**2) in O(x)");
  it("O(x)*x", () => {
    const x = new Sym('x');
    expect(sympyStr(O(x, x, rational(0)).mul(x))).toBe('O(x**2)');
  });
  it("O(x) - O(x)", () => {
    const x = new Sym('x');
    expect(sympyStr(O(x, x, rational(0)).sub(O(x, x, rational(0))))).toBe('O(x)');
  });
  it("O(cos(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(O(fn('cos', [x])))).toBe('O(1)');
  });
  it("O(cos(x), (x, pi/2))", () => {
    const x = new Sym('x');
    expect(sympyStr(O(fn('cos', [x]), x, mul(rational(1, 2), pi)))).toBe('O(x - pi/2, (x, pi/2))');
  });
});

describe("doctests of sympy.core.operations", () => {
  it("e.args", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr([rational(3), x, y], 't')).toBe('(3, x, y)');
  });
  it("m == x", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("m.is_Mul", () => {
    const x = new Sym('x');
    expect(sympyStr(isMul(new Mul([rational(1), x])))).toBe('True');
  });
  it("Mul.make_args(x*y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyMatches([x, y], '(x, y)')).toBe(true);
  });
  it("Add.make_args(x*y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyMatches([mul(x, y)], '(x*y,)')).toBe(true);
  });
  it("set(Add.make_args(x*y + y)) == set([y, x*y])", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(mul(x, y).equals(mul(x, y)))).toBe('True');
  });
});

describe("doctests of sympy.core.singleton", () => {
  it("0 == S.Zero", () => {
    expect(sympyStr(rational(0).equals(rational(0)))).toBe('True');
  });
});

